using System;using System.Linq;using System.IO;using System.Windows;using System.Windows.Controls;
namespace Touchfish {public partial class PanelWindow {
 public void PreviewSealedScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;if(VerificationRun.Visual){lanSealedMode=true;lanIsHost=true;sealedSession=new SealedSession(catalog,77861,matchRules.Supports);sealedView=sealedSession.View(0);ApplyTheme(true,true);ApplyMode(false);RenderSealed();Render(Path.Combine(folder,"sealed-class-normal.png"));SealedAction("class",sealedView.Classes[0]);SealedAction("open");Render(Path.Combine(folder,"sealed-pack-normal.png"));SealedAction("open-all");var columns=(Grid)sealedStage.Children.Cast<UIElement>().First(e=>Grid.GetRow(e)==2);var rows=(StackPanel)((ScrollViewer)columns.Children[0]).Content;var plus=rows.Children.OfType<Grid>().First().Children.OfType<Button>().Single();plus.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(sealedView.Deck.Values.Sum()==1,"Actual builder plus button adds an owned card");foreach(var entry in sealedView.Pool.Take(5).ToArray())if(sealedView.Deck.Values.Sum()<6)SealedAction("edit",entry.Key,1);Render(Path.Combine(folder,"sealed-build-normal.png"));ApplyMode(true);RenderSealed();Render(Path.Combine(folder,"sealed-build-minimal.png"));Check(Width==392&&Height==300&&sealedStage.ActualHeight==170,"Sealed builder fits fixed minimal window");ApplyMode(false);ResetSealed();HideSealed();}
  VerifySealedTcp();File.WriteAllText(Path.Combine(folder,"sealed-verification.txt"),"PASS "+(checks-before)+" checks; WPF="+VerificationRun.Visual+"; loopback TCP="+VerificationRun.Network+"; no real user data writes.");
 }
 void FillSealedUi(PanelWindow window){if(window.sealedView.Phase=="class"){window.SealedAction("class",window.sealedView.Classes[0]);if(!window.lanIsHost)PumpLan(()=>!window.lanWaiting,"Class choice acknowledged");}if(window.sealedView.Opened<18){window.SealedAction("open-all");if(!window.lanIsHost)PumpLan(()=>!window.lanWaiting,"Opening eighteen packs acknowledged");}foreach(var pair in window.sealedView.Pool.ToArray()){for(int n=0;n<pair.Value&&window.sealedView.Deck.Values.Sum()<30;n++){window.SealedAction("edit",pair.Key,1);if(!window.lanIsHost)PumpLan(()=>!window.lanWaiting,"Private deck edit acknowledged");}}}
 void VerifySealedTcp(){if(!VerificationRun.Network)return;LeaveLan();var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{lanPort.Text=FreeLanPort().ToString();lanModePicker.SelectedItem=((Choice[])lanModePicker.ItemsSource).First(c=>c.Key=="sealed");BeginLan(true);guest.lanModePicker.SelectedItem=((Choice[])guest.lanModePicker.ItemsSource).First(c=>c.Key=="sealed");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>sealedSession!=null&&guest.sealedView!=null,"Sealed peers complete handshake");
   SealedAction("class",sealedView.Classes[0]);SealedAction("open-all");PumpLan(()=>guest.sealedView.OpponentOpened==18,"Opponent receives opening progress");Check(guest.sealedView.Pool.Count==0&&guest.sealedView.LastPack.Length==0,"Opening progress does not leak opponent card pool or last pack");FillSealedUi(this);FillSealedUi(guest);var pool=String.Join(",",guest.sealedView.Pool.Select(p=>p.Key+":"+p.Value));SealedAction("confirm");guest.SealedAction("confirm");PumpLan(()=>lanReady&&guest.lanReady,"Both confirmed decks start sealed match");Check(match.Mode.Id=="sealed"&&guest.match.Mode.Id=="sealed"&&CanMulliganInput()&&guest.CanMulliganInput(),"Sealed initial state unlocks both mulligans");CheckMulliganCardClick(this,"Sealed host can select replacement");CheckMulliganCardClick(guest,"Sealed guest can select replacement");
   FinishArenaGameWithFireball(guest,0);PumpLan(()=>sealedSession.Round==2&&guest.sealedView.Round==2&&!guest.lanReady,"First result opens between-game rebuild");Check(pool==String.Join(",",guest.sealedView.Pool.Select(p=>p.Key+":"+p.Value))&&guest.sealedView.Opened==18,"Rebuild retains exactly the initial ninety cards without new packs");string removed=guest.sealedView.Deck.Keys.First();guest.SealedAction("edit",removed,-1);PumpLan(()=>!guest.lanWaiting,"Rebuild removal acknowledged");string added=guest.sealedView.Pool.Keys.First(id=>id!=removed&&(!guest.sealedView.Deck.ContainsKey(id)||guest.sealedView.Deck[id]<guest.sealedView.Pool[id]));guest.SealedAction("edit",added,1);PumpLan(()=>!guest.lanWaiting,"Rebuild addition acknowledged");guest.SealedAction("confirm");PumpLan(()=>!guest.lanWaiting,"Guest confirms rebuild");SealedAction("confirm");PumpLan(()=>lanReady&&guest.lanReady&&!guest.match.MulliganComplete,"Rebuilt decks start second game with fresh mulligan");Check(guest.lanArenaWins1==1&&guest.lanArenaGameNumber==2,"Series score and game number synchronize");FinishArenaGameWithFireball(guest,0);PumpLan(()=>sealedSession.SeriesWinner==1&&guest.lanArenaSeriesWinner==1,"Two wins finish sealed series");Check(sealedSession.Round==2&&sealedSession.Wins1==2,"Completed series does not need a third game");
  }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}}
